-- Ejercicios que compartian las instrucciones con otro ejercicio distinto, y por
-- eso describian un movimiento que no era el suyo. Cada uno recibe su texto.
-- Se identifican por su codigo (externalId).
--
-- El texto de busqueda (searchName) lleva las instrucciones adentro: se reemplaza
-- esa parte.
--
-- La copia de cada entrenador se actualiza solo si conserva el texto original.

-- 1307: Flexión de brazos sobre BOSU
UPDATE "ExerciseCoach" SET "instructions" = 'Coloca el bosu en el suelo con la cúpula hacia arriba. Apoya las dos manos sobre la cúpula, a la altura de los hombros, y extiende las piernas hacia atrás hasta quedar en posición de flexión de brazos. Activa el abdomen para mantener el equilibrio y baja el pecho hacia el bosu flexionando los codos. Empuja hacia arriba hasta extender los brazos. Repite el número de repeticiones deseado.', "searchName" = replace( "searchName", 'coloca el bosu en el suelo con el lado plano hacia arriba. colocate en posicion de flexion con las manos en los bordes exteriores del bosu. activa el core y baja el cuerpo hacia el bosu flexionando los codos. empuja tu cuerpo de vuelta a la posicion inicial extendiendo los brazos. repite el numero de repeticiones deseado.', 'coloca el bosu en el suelo con la cupula hacia arriba. apoya las dos manos sobre la cupula, a la altura de los hombros, y extiende las piernas hacia atras hasta quedar en posicion de flexion de brazos. activa el abdomen para mantener el equilibrio y baja el pecho hacia el bosu flexionando los codos. empuja hacia arriba hasta extender los brazos. repite el numero de repeticiones deseado.' )
WHERE "instructions" = 'Coloca el bosu en el suelo con el lado plano hacia arriba. Colócate en posición de flexión con las manos en los bordes exteriores del bosu. Activa el core y baja el cuerpo hacia el bosu flexionando los codos. Empuja tu cuerpo de vuelta a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.' AND "globalExerciseId" IN ( SELECT "id" FROM "ExerciseGlobal" WHERE "externalId" = '1307' );
UPDATE "ExerciseCoach" SET "tips" = 'Coloca el bosu en el suelo con la cúpula hacia arriba. Apoya las dos manos sobre la cúpula, a la altura de los hombros, y extiende las piernas hacia atrás hasta quedar en posición de flexión de brazos. Activa el abdomen para mantener el equilibrio y baja el pecho hacia el bosu flexionando los codos. Empuja hacia arriba hasta extender los brazos. Repite el número de repeticiones deseado.'
WHERE "tips" = 'Coloca el bosu en el suelo con el lado plano hacia arriba. Colócate en posición de flexión con las manos en los bordes exteriores del bosu. Activa el core y baja el cuerpo hacia el bosu flexionando los codos. Empuja tu cuerpo de vuelta a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.' AND "globalExerciseId" IN ( SELECT "id" FROM "ExerciseGlobal" WHERE "externalId" = '1307' );
UPDATE "ExerciseGlobal" SET "instructions" = 'Coloca el bosu en el suelo con la cúpula hacia arriba. Apoya las dos manos sobre la cúpula, a la altura de los hombros, y extiende las piernas hacia atrás hasta quedar en posición de flexión de brazos. Activa el abdomen para mantener el equilibrio y baja el pecho hacia el bosu flexionando los codos. Empuja hacia arriba hasta extender los brazos. Repite el número de repeticiones deseado.', "searchName" = replace( "searchName", 'coloca el bosu en el suelo con el lado plano hacia arriba. colocate en posicion de flexion con las manos en los bordes exteriores del bosu. activa el core y baja el cuerpo hacia el bosu flexionando los codos. empuja tu cuerpo de vuelta a la posicion inicial extendiendo los brazos. repite el numero de repeticiones deseado.', 'coloca el bosu en el suelo con la cupula hacia arriba. apoya las dos manos sobre la cupula, a la altura de los hombros, y extiende las piernas hacia atras hasta quedar en posicion de flexion de brazos. activa el abdomen para mantener el equilibrio y baja el pecho hacia el bosu flexionando los codos. empuja hacia arriba hasta extender los brazos. repite el numero de repeticiones deseado.' )
WHERE "externalId" = '1307' AND "instructions" = 'Coloca el bosu en el suelo con el lado plano hacia arriba. Colócate en posición de flexión con las manos en los bordes exteriores del bosu. Activa el core y baja el cuerpo hacia el bosu flexionando los codos. Empuja tu cuerpo de vuelta a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.';

-- 1441: Curl inverso de muñeca sobre banco a una mano con mancuerna
UPDATE "ExerciseCoach" SET "instructions" = 'Arrodíllate junto a un banco plano y apoya un antebrazo a lo ancho del banco, con la mano sobresaliendo del borde y la palma hacia abajo, sujetando una mancuerna. Deja que la muñeca baje. Extiende la muñeca hacia arriba, llevando el dorso de la mano hacia el antebrazo sin despegarlo del banco. Haz una pausa breve arriba y baja de forma controlada. Repite el número de repeticiones deseado. Luego cambia de brazo.', "searchName" = replace( "searchName", 'sientate en un banco con los pies apoyados en el suelo y sujeta una mancuerna con una mano, con la palma hacia abajo. apoya el antebrazo en el banco con la muneca colgando del borde. flexiona lentamente la muneca hacia arriba, acercando la mancuerna hacia el antebrazo. haz una pausa breve en la parte mas alta, luego baja lentamente la mancuerna de vuelta a la posicion inicial. repite el numero de repeticiones deseado, luego cambia al otro brazo.', 'arrodillate junto a un banco plano y apoya un antebrazo a lo ancho del banco, con la mano sobresaliendo del borde y la palma hacia abajo, sujetando una mancuerna. deja que la muneca baje. extiende la muneca hacia arriba, llevando el dorso de la mano hacia el antebrazo sin despegarlo del banco. haz una pausa breve arriba y baja de forma controlada. repite el numero de repeticiones deseado. luego cambia de brazo.' )
WHERE "instructions" = 'Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna con una mano, con la palma hacia abajo. Apoya el antebrazo en el banco con la muñeca colgando del borde. Flexiona lentamente la muñeca hacia arriba, acercando la mancuerna hacia el antebrazo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.' AND "globalExerciseId" IN ( SELECT "id" FROM "ExerciseGlobal" WHERE "externalId" = '1441' );
UPDATE "ExerciseCoach" SET "tips" = 'Arrodíllate junto a un banco plano y apoya un antebrazo a lo ancho del banco, con la mano sobresaliendo del borde y la palma hacia abajo, sujetando una mancuerna. Deja que la muñeca baje. Extiende la muñeca hacia arriba, llevando el dorso de la mano hacia el antebrazo sin despegarlo del banco. Haz una pausa breve arriba y baja de forma controlada. Repite el número de repeticiones deseado. Luego cambia de brazo.'
WHERE "tips" = 'Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna con una mano, con la palma hacia abajo. Apoya el antebrazo en el banco con la muñeca colgando del borde. Flexiona lentamente la muñeca hacia arriba, acercando la mancuerna hacia el antebrazo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.' AND "globalExerciseId" IN ( SELECT "id" FROM "ExerciseGlobal" WHERE "externalId" = '1441' );
