WHERE "externalId" = '2405' AND "instructions" = 'Coloca un accesorio en V en la máquina de cable en el ajuste más alto. Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Agarra el accesorio en V con un agarre prono, con las palmas hacia abajo y las manos separadas a la altura de los hombros. Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio. Activa los tríceps y exhala mientras empujas el accesorio en V hacia abajo hasta que los brazos estén completamente extendidos. Haz una pausa breve en la parte baja del movimiento, apretando los tríceps. Inhala mientras regresas lentamente el accesorio en V a la posición inicial, manteniendo el control. Repite el número de repeticiones deseado.';

-- 3201: Abdominal de cuarto
UPDATE "ExerciseCoach" SET "instructions" = 'Túmbate boca arriba con las piernas extendidas y los brazos a los lados del cuerpo. Activa el abdomen y despega del suelo solo la cabeza y los hombros, un cuarto del recorrido, deslizando las manos hacia los pies. Haz una pausa breve arriba y baja de forma controlada. Repite el número de repeticiones deseado.', "searchName" = replace( "searchName", 'tumbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. coloca las manos detras de la cabeza con los codos apuntando hacia afuera. activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvandote hacia adelante hasta que tu torso forme un angulo de 45 grados. haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posicion inicial. repite el numero de repeticiones deseado.', 'tumbate boca arriba con las piernas extendidas y los brazos a los lados del cuerpo. activa el abdomen y despega del suelo solo la cabeza y los hombros, un cuarto del recorrido, deslizando las manos hacia los pies. haz una pausa breve arriba y baja de forma controlada. repite el numero de repeticiones deseado.' )
WHERE "instructions" = 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.' AND "globalExerciseId" IN ( SELECT "id" FROM "ExerciseGlobal" WHERE "externalId" = '3201' );
UPDATE "ExerciseCoach" SET "tips" = 'Túmbate boca arriba con las piernas extendidas y los brazos a los lados del cuerpo. Activa el abdomen y despega del suelo solo la cabeza y los hombros, un cuarto del recorrido, deslizando las manos hacia los pies. Haz una pausa breve arriba y baja de forma controlada. Repite el número de repeticiones deseado.'
WHERE "tips" = 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.' AND "globalExerciseId" IN ( SELECT "id" FROM "ExerciseGlobal" WHERE "externalId" = '3201' );
