WHERE "externalId" = '3201' AND "instructions" = 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.';

-- 3202: Abdominal medio
UPDATE "ExerciseCoach" SET "instructions" = 'Túmbate boca arriba con las piernas extendidas y los brazos a los lados del cuerpo. Activa el abdomen y levanta el torso hasta quedar sentado, con la espalda derecha y las piernas apoyadas en el suelo. Baja de forma controlada, apoyando la espalda vértebra por vértebra, hasta la posición inicial. Repite el número de repeticiones deseado.', "searchName" = replace( "searchName", 'tumbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. coloca las manos detras de la cabeza con los codos apuntando hacia afuera. activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvandote hacia adelante hasta que tu torso forme un angulo de 45 grados. haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posicion inicial. repite el numero de repeticiones deseado.', 'tumbate boca arriba con las piernas extendidas y los brazos a los lados del cuerpo. activa el abdomen y levanta el torso hasta quedar sentado, con la espalda derecha y las piernas apoyadas en el suelo. baja de forma controlada, apoyando la espalda vertebra por vertebra, hasta la posicion inicial. repite el numero de repeticiones deseado.' )
WHERE "instructions" = 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.' AND "globalExerciseId" IN ( SELECT "id" FROM "ExerciseGlobal" WHERE "externalId" = '3202' );
