-- 0367: Curl de muñeca sobre banco a una mano con mancuerna
UPDATE "ExerciseCoach" SET "instructions" = 'Arrodíllate junto a un banco plano y apoya un antebrazo a lo ancho del banco, con la mano sobresaliendo del borde y la palma hacia arriba, sujetando una mancuerna. Deja que la muñeca baje para estirar el antebrazo. Flexiona la muñeca hacia arriba, acercando la mancuerna al antebrazo sin despegarlo del banco. Haz una pausa breve arriba y baja de forma controlada. Repite el número de repeticiones deseado. Luego cambia de brazo.', "searchName" = replace( "searchName", 'sientate en un banco con los pies apoyados en el suelo y sujeta una mancuerna con una mano, con la palma hacia abajo. apoya el antebrazo en el banco con la muneca colgando del borde. flexiona lentamente la muneca hacia arriba, acercando la mancuerna hacia el antebrazo. haz una pausa breve en la parte mas alta, luego baja lentamente la mancuerna de vuelta a la posicion inicial. repite el numero de repeticiones deseado, luego cambia al otro brazo.', 'arrodillate junto a un banco plano y apoya un antebrazo a lo ancho del banco, con la mano sobresaliendo del borde y la palma hacia arriba, sujetando una mancuerna. deja que la muneca baje para estirar el antebrazo. flexiona la muneca hacia arriba, acercando la mancuerna al antebrazo sin despegarlo del banco. haz una pausa breve arriba y baja de forma controlada. repite el numero de repeticiones deseado. luego cambia de brazo.' )
WHERE "instructions" = 'Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna con una mano, con la palma hacia abajo. Apoya el antebrazo en el banco con la muñeca colgando del borde. Flexiona lentamente la muñeca hacia arriba, acercando la mancuerna hacia el antebrazo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.' AND "globalExerciseId" IN ( SELECT "id" FROM "ExerciseGlobal" WHERE "externalId" = '0367' );
