-- 0472: Elevación de piernas colgado
UPDATE "ExerciseCoach" SET "instructions" = 'Cuélgate de una barra de dominadas con los brazos extendidos y las palmas hacia adelante. Activa el abdomen y sube las rodillas hacia el pecho, flexionando las piernas, sin balancear el cuerpo. Haz una pausa breve arriba y baja las piernas de forma controlada hasta quedar colgado y estirado. Repite el número de repeticiones deseado.', "searchName" = replace( "searchName", 'cuelgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera. activa el core y levanta las piernas frente a ti, manteniendolas rectas. continua levantando hasta que las piernas esten paralelas al suelo o tan alto como puedas llegar comodamente. haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posicion inicial. repite el numero de repeticiones deseado.', 'cuelgate de una barra de dominadas con los brazos extendidos y las palmas hacia adelante. activa el abdomen y sube las rodillas hacia el pecho, flexionando las piernas, sin balancear el cuerpo. haz una pausa breve arriba y baja las piernas de forma controlada hasta quedar colgado y estirado. repite el numero de repeticiones deseado.' )
WHERE "instructions" = 'Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera. Activa el core y levanta las piernas frente a ti, manteniéndolas rectas. Continúa levantando hasta que las piernas estén paralelas al suelo o tan alto como puedas llegar cómodamente. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.' AND "globalExerciseId" IN ( SELECT "id" FROM "ExerciseGlobal" WHERE "externalId" = '0472' );
