-- 0454: Curl spider con barra EZ (apoyado en banco inclinado)
UPDATE "ExerciseCoach" SET "instructions" = 'Túmbate boca abajo sobre un banco inclinado, con el pecho apoyado en el respaldo y los pies en el suelo. Sujeta la barra EZ con agarre supino y deja los brazos colgando rectos hacia el suelo. Sin mover la parte superior de los brazos, exhala y flexiona los codos para subir la barra hacia los hombros. Aprieta los bíceps un momento arriba y baja de forma controlada hasta extender los brazos. Repite el número de repeticiones deseado.', "searchName" = replace( "searchName", 'ponte de pie con los pies separados a la altura de los hombros y sosten la barra ez con agarre supino, palmas hacia arriba. apoya los brazos superiores en un banco scott o en un balon de estabilidad, dejando que los codos cuelguen hacia abajo. manteniendo los brazos superiores fijos, exhala y levanta la barra hacia los hombros. haz una pausa breve en la parte alta, apretando los biceps. inhala y baja lentamente la barra de vuelta a la posicion inicial. repite el numero de repeticiones deseado.', 'tumbate boca abajo sobre un banco inclinado, con el pecho apoyado en el respaldo y los pies en el suelo. sujeta la barra ez con agarre supino y deja los brazos colgando rectos hacia el suelo. sin mover la parte superior de los brazos, exhala y flexiona los codos para subir la barra hacia los hombros. aprieta los biceps un momento arriba y baja de forma controlada hasta extender los brazos. repite el numero de repeticiones deseado.' )
WHERE "instructions" = 'Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino, palmas hacia arriba. Apoya los brazos superiores en un banco scott o en un balón de estabilidad, dejando que los codos cuelguen hacia abajo. Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia los hombros. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.' AND "globalExerciseId" IN ( SELECT "id" FROM "ExerciseGlobal" WHERE "externalId" = '0454' );
