-- 0735: Abdominal (variante 2)
UPDATE "ExerciseCoach" SET "instructions" = 'Túmbate boca arriba con las rodillas flexionadas, los pies apoyados en el suelo y las manos detrás de la cabeza. Activa el abdomen y levanta el torso por completo hasta quedar sentado, cerca de las rodillas, sin tirar del cuello. Baja de forma controlada hasta apoyar toda la espalda. Repite el número de repeticiones deseado.', "searchName" = replace( "searchName", 'tumbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. coloca las manos detras de la cabeza con los codos apuntando hacia afuera. activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvandote hacia adelante hasta que tu torso forme un angulo de 45 grados. haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posicion inicial. repite el numero de repeticiones deseado.', 'tumbate boca arriba con las rodillas flexionadas, los pies apoyados en el suelo y las manos detras de la cabeza. activa el abdomen y levanta el torso por completo hasta quedar sentado, cerca de las rodillas, sin tirar del cuello. baja de forma controlada hasta apoyar toda la espalda. repite el numero de repeticiones deseado.' )
WHERE "instructions" = 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.' AND "globalExerciseId" IN ( SELECT "id" FROM "ExerciseGlobal" WHERE "externalId" = '0735' );
UPDATE "ExerciseCoach" SET "tips" = 'Túmbate boca arriba con las rodillas flexionadas, los pies apoyados en el suelo y las manos detrás de la cabeza. Activa el abdomen y levanta el torso por completo hasta quedar sentado, cerca de las rodillas, sin tirar del cuello. Baja de forma controlada hasta apoyar toda la espalda. Repite el número de repeticiones deseado.'
WHERE "tips" = 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.' AND "globalExerciseId" IN ( SELECT "id" FROM "ExerciseGlobal" WHERE "externalId" = '0735' );
UPDATE "ExerciseGlobal" SET "instructions" = 'Túmbate boca arriba con las rodillas flexionadas, los pies apoyados en el suelo y las manos detrás de la cabeza. Activa el abdomen y levanta el torso por completo hasta quedar sentado, cerca de las rodillas, sin tirar del cuello. Baja de forma controlada hasta apoyar toda la espalda. Repite el número de repeticiones deseado.', "searchName" = replace( "searchName", 'tumbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. coloca las manos detras de la cabeza con los codos apuntando hacia afuera. activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvandote hacia adelante hasta que tu torso forme un angulo de 45 grados. haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posicion inicial. repite el numero de repeticiones deseado.', 'tumbate boca arriba con las rodillas flexionadas, los pies apoyados en el suelo y las manos detras de la cabeza. activa el abdomen y levanta el torso por completo hasta quedar sentado, cerca de las rodillas, sin tirar del cuello. baja de forma controlada hasta apoyar toda la espalda. repite el numero de repeticiones deseado.' )
WHERE "externalId" = '0735' AND "instructions" = 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.';

-- 0001: Crunch 3/4
UPDATE "ExerciseCoach" SET "instructions" = 'Túmbate boca arriba con las rodillas flexionadas, los pies apoyados en el suelo y las manos detrás de la cabeza. Activa el abdomen y levanta el torso hasta unas tres cuartas partes del recorrido, sin llegar a quedar sentado del todo. Haz una pausa breve y baja de forma controlada, sin apoyar por completo los hombros entre repeticiones. Repite el número de repeticiones deseado.', "searchName" = replace( "searchName", 'tumbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. coloca las manos detras de la cabeza con los codos apuntando hacia afuera. activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvandote hacia adelante hasta que tu torso forme un angulo de 45 grados. haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posicion inicial. repite el numero de repeticiones deseado.', 'tumbate boca arriba con las rodillas flexionadas, los pies apoyados en el suelo y las manos detras de la cabeza. activa el abdomen y levanta el torso hasta unas tres cuartas partes del recorrido, sin llegar a quedar sentado del todo. haz una pausa breve y baja de forma controlada, sin apoyar por completo los hombros entre repeticiones. repite el numero de repeticiones deseado.' )
WHERE "instructions" = 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.' AND "globalExerciseId" IN ( SELECT "id" FROM "ExerciseGlobal" WHERE "externalId" = '0001' );
