-- 0376: Elevación con mancuernas
UPDATE "ExerciseCoach" SET "instructions" = 'Ponte de pie con los pies separados a la altura de los hombros y una mancuerna en cada mano, apoyadas frente a los muslos con las palmas hacia el cuerpo. Exhala y sube las mancuernas pegadas al cuerpo hasta la altura del pecho, llevando los codos hacia arriba y hacia afuera, por encima de las manos. Haz una pausa breve arriba y baja de forma controlada hasta extender los brazos. Repite el número de repeticiones deseado.', "searchName" = replace( "searchName", 'ponte de pie con los pies separados a la altura de los hombros y sosten una mancuerna en cada mano, con las palmas hacia el cuerpo. manten la espalda recta y activa el core. levanta los brazos hacia los lados hasta que queden paralelos al suelo, manteniendo una ligera flexion en los codos. haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posicion inicial. repite el numero de repeticiones deseado.', 'ponte de pie con los pies separados a la altura de los hombros y una mancuerna en cada mano, apoyadas frente a los muslos con las palmas hacia el cuerpo. exhala y sube las mancuernas pegadas al cuerpo hasta la altura del pecho, llevando los codos hacia arriba y hacia afuera, por encima de las manos. haz una pausa breve arriba y baja de forma controlada hasta extender los brazos. repite el numero de repeticiones deseado.' )
WHERE "instructions" = 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano, con las palmas hacia el cuerpo. Mantén la espalda recta y activa el core. Levanta los brazos hacia los lados hasta que queden paralelos al suelo, manteniendo una ligera flexión en los codos. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.' AND "globalExerciseId" IN ( SELECT "id" FROM "ExerciseGlobal" WHERE "externalId" = '0376' );
