-- 0164: Elevación frontal de hombros en polea
UPDATE "ExerciseCoach" SET "instructions" = 'Colócate de pie en el centro de un cruce de poleas, de espaldas a la máquina, con las dos poleas en la posición baja. Sujeta una agarradera en cada mano, con los brazos a los lados. Con los brazos casi extendidos, exhala y sube las dos manos por delante del cuerpo hasta la altura de los hombros. Haz una pausa breve arriba y baja de forma controlada, sin dejar que el peso te tire hacia atrás. Repite el número de repeticiones deseado.', "searchName" = replace( "searchName", 'ponte de pie con los pies separados a la altura de los hombros y sujeta la agarradera del cable con agarre prono. manten la espalda recta y el core activado. levanta la agarradera del cable frente a ti, manteniendo los brazos rectos y las palmas hacia abajo. continua levantando hasta que los brazos queden paralelos al suelo. haz una pausa breve en la parte mas alta, luego baja lentamente la agarradera del cable de vuelta a la posicion inicial. repite el numero de repeticiones deseado.', 'colocate de pie en el centro de un cruce de poleas, de espaldas a la maquina, con las dos poleas en la posicion baja. sujeta una agarradera en cada mano, con los brazos a los lados. con los brazos casi extendidos, exhala y sube las dos manos por delante del cuerpo hasta la altura de los hombros. haz una pausa breve arriba y baja de forma controlada, sin dejar que el peso te tire hacia atras. repite el numero de repeticiones deseado.' )
WHERE "instructions" = 'Ponte de pie con los pies separados a la altura de los hombros y sujeta la agarradera del cable con agarre prono. Mantén la espalda recta y el core activado. Levanta la agarradera del cable frente a ti, manteniendo los brazos rectos y las palmas hacia abajo. Continúa levantando hasta que los brazos queden paralelos al suelo. Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado.' AND "globalExerciseId" IN ( SELECT "id" FROM "ExerciseGlobal" WHERE "externalId" = '0164' );
