-- 0685: Correr
UPDATE "ExerciseCoach" SET "instructions" = 'Empieza con un trote suave para entrar en calor. Corre con el torso erguido, la mirada al frente y los hombros relajados. Mueve los brazos flexionados a unos 90 grados, hacia adelante y atrás, sin cruzarlos por delante del cuerpo. Apoya el pie debajo de la cadera, con pasos cortos y un ritmo constante, y respira de forma regular. Mantén el ritmo durante el tiempo o la distancia que te hayan indicado y termina bajando la velocidad de a poco.', "searchName" = replace( "searchName", 'comienza de pie con los pies separados a la altura de la cadera. activa el core y manten la parte superior del cuerpo relajada. comienza a trotar en el lugar, levantando las rodillas hacia el pecho y aterrizando suavemente sobre la punta de los pies. manten un ritmo constante y continua trotando durante la duracion o distancia deseada. recuerda respirar profundamente y mantener una buena postura durante todo el ejercicio.', 'empieza con un trote suave para entrar en calor. corre con el torso erguido, la mirada al frente y los hombros relajados. mueve los brazos flexionados a unos 90 grados, hacia adelante y atras, sin cruzarlos por delante del cuerpo. apoya el pie debajo de la cadera, con pasos cortos y un ritmo constante, y respira de forma regular. manten el ritmo durante el tiempo o la distancia que te hayan indicado y termina bajando la velocidad de a poco.' )
WHERE "instructions" = 'Comienza de pie con los pies separados a la altura de la cadera. Activa el core y mantén la parte superior del cuerpo relajada. Comienza a trotar en el lugar, levantando las rodillas hacia el pecho y aterrizando suavemente sobre la punta de los pies. Mantén un ritmo constante y continúa trotando durante la duración o distancia deseada. Recuerda respirar profundamente y mantener una buena postura durante todo el ejercicio.' AND "globalExerciseId" IN ( SELECT "id" FROM "ExerciseGlobal" WHERE "externalId" = '0685' );
UPDATE "ExerciseCoach" SET "tips" = 'Empieza con un trote suave para entrar en calor. Corre con el torso erguido, la mirada al frente y los hombros relajados. Mueve los brazos flexionados a unos 90 grados, hacia adelante y atrás, sin cruzarlos por delante del cuerpo. Apoya el pie debajo de la cadera, con pasos cortos y un ritmo constante, y respira de forma regular. Mantén el ritmo durante el tiempo o la distancia que te hayan indicado y termina bajando la velocidad de a poco.'
